# Generic package name -> package per distro family.
#
#   name  arch  debian  fedora  suse
#
# Omarchy uses the arch column. A cell lists alternatives separated by "|",
# tried in order; the first one this machine can provide wins. Join several
# packages for one alternative with ",". Prefixes: aur: (via yay/paru; yay
# also takes repo packages, so Omarchy's own repo is used first) and flatpak:
# (a Flathub app id). "-" means not offered on that family.
#
# name                arch                                      debian                                   fedora                                   suse

# --- bootstrap --------------------------------------------------------------
git                   git                                       git                                      git                                      git
curl                  curl                                      curl                                     curl                                     curl
jq                    jq                                        jq                                       jq                                       jq
gum                   gum                                       gum|-                                    gum|-                                    gum|-
build-tools           base-devel                                build-essential                          gcc,gcc-c++,make                         gcc,gcc-c++,make
unzip                 unzip                                     unzip                                    unzip                                    unzip

# --- desktop ----------------------------------------------------------------
gnome-keyring         gnome-keyring                             gnome-keyring                            gnome-keyring                            gnome-keyring
portal-gtk            xdg-desktop-portal-gtk                    xdg-desktop-portal-gtk                   xdg-desktop-portal-gtk                   xdg-desktop-portal-gtk
fuse2                 fuse2                                     libfuse2t64|libfuse2                     fuse-libs                                libfuse2
libsecret             libsecret                                 libsecret-1-0                            libsecret                                libsecret-1-0
wpewebkit             wpewebkit                                 -                                        -                                        -
socat                 socat                                     socat                                    socat                                    socat
owe-lockfeed          owe-lockfeed                              -                                        -                                        -

